def process(marineExceedanceDiff, summerRainDiff):
    import pandas as pd

    y1 = int(marineExceedanceDiff.iloc[0]['yearMaxExceedDiff'])
    y2 = int(summerRainDiff.iloc[0]['yearMaxRainDiff'])

    return pd.DataFrame([{
        'yearMaxExceedDiff': y1,
        'yearMaxRainDiff': y2,
        'sameYear': bool(y1 == y2)
    }])
